using System.Text.Json;

namespace Vybe.GameRules.Tests;

/// <summary>Cross-language parity for Street Juggle: C# must reproduce every fixture generated by the TS reference.</summary>
public sealed class JuggleGoldenFixtureTests
{
    public static TheoryData<string> ScoringFixtures() => new(FixtureFiles.List("street-juggle/scoring"));

    public static TheoryData<string> RejectionFixtures() => new(FixtureFiles.List("street-juggle/rejections"));

    [Fact]
    public void RulesetChecksum_MatchesCanonicalJsonOfConfig()
    {
        using var document = FixtureFiles.ReadDocument("rulesets/street-juggle-v1.json");
        var root = document.RootElement;

        Assert.Equal("street-juggle", root.GetProperty("gameId").GetString());
        Assert.Equal(root.GetProperty("checksum").GetString(), CanonicalJson.Checksum(root.GetProperty("config")));
    }

    [Theory]
    [MemberData(nameof(ScoringFixtures))]
    [MemberData(nameof(RejectionFixtures))]
    public void Evaluate_ReproducesFixture(string relativePath)
    {
        var fixture = FixtureFiles.Read<JuggleFixture>(relativePath);

        var result = StreetJuggleSimulator.Evaluate(fixture.Input);
        var actual = JsonSerializer.SerializeToElement(result, FixtureFiles.JsonOptions);
        Assert.Equal(CanonicalJson.Serialize(fixture.Expected), CanonicalJson.Serialize(actual));
    }

    [Fact]
    public void FixtureDirectories_AreNotEmpty()
    {
        Assert.True(FixtureFiles.List("street-juggle/scoring").Count() > 10);
        Assert.True(FixtureFiles.List("street-juggle/rejections").Count() > 10);
    }
}
